"""Read-only access to the question bank generated by tools/build-content.mjs."""
import json
import os
from functools import lru_cache
from pathlib import Path

DEFAULT_BANK = Path(__file__).parent / "content" / "bank.json"


def bank_path() -> Path:
    return Path(os.environ.get("CONTENT_BANK", str(DEFAULT_BANK)))


class Bank:
    def __init__(self, raw: dict):
        self.modules = {m["id"]: m for m in raw["modules"]}
        self.module_order = [m["id"] for m in raw["modules"]]
        self.scenes = raw.get("scenes", {})
        self.badges = set(raw.get("badges", []))
        self.module_badges = raw.get("moduleBadges", {})
        self.questions = {}
        for module in raw["modules"]:
            for q in module["quiz"]:
                self.questions[q["id"]] = {**q, "moduleId": module["id"]}

    def module(self, module_id: str):
        return self.modules.get(module_id)

    def lesson_refs(self, module_id: str):
        module = self.modules[module_id]
        return [f"{module_id}:{i}" for i in range(module["lessons"])]

    def all_lesson_refs(self):
        return [ref for mid in self.module_order for ref in self.lesson_refs(mid)]

    def all_question_ids(self):
        return list(self.questions.keys())

    def public_question(self, qid: str) -> dict:
        q = self.questions[qid]
        module = self.modules[q["moduleId"]]
        return {
            "id": qid,
            "question": q["question"],
            "options": q["options"],
            "moduleId": module["id"],
            "moduleTitle": module["title"],
            "moduleIcon": module["icon"],
        }


@lru_cache(maxsize=1)
def get_bank() -> Bank:
    with open(bank_path(), encoding="utf-8") as fh:
        return Bank(json.load(fh))


def reload_bank():
    get_bank.cache_clear()
